// Run against an isolated demo server. Uses fixture files generated by make_fixtures.
const {chromium} = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');

(async () => {
  const browser = await chromium.launch({channel: 'msedge', headless: true});
  const errors = [];
  const results = {};
  try {
    const page = await browser.newPage({viewport: {width: 1440, height: 1080}});
    page.setDefaultTimeout(15000);
    page.on('pageerror', e => errors.push(e.message));
    await page.goto(process.env.STUDY_URL || 'http://127.0.0.1:8765');
    await page.locator('#mode').filter({hasText: '演示模式'}).waitFor();
    await page.locator('#course-name').fill('人工智能 · 工作台验收');
    await page.locator('#course-form button').click();
    await page.locator('#status').filter({hasText: '课程已创建'}).waitFor();
    const course = await page.locator('#course').inputValue();
    await page.locator('#document-type').selectOption('notes');
    // Exercise a real drop event with the same bytes as a user-selected DOCX.
    const data = fs.readFileSync(path.resolve('data/phase3-notes.docx')).toString('base64');
    await page.locator('#drop-zone').evaluate((zone, encoded) => {
      const bytes = Uint8Array.from(atob(encoded), c => c.charCodeAt(0));
      const transfer = new DataTransfer();
      transfer.items.add(new File([bytes], '搜索算法笔记.docx'));
      zone.dispatchEvent(new DragEvent('drop', {bubbles: true, cancelable: true, dataTransfer: transfer}));
    }, data);
    await page.locator('#file-caption').filter({hasText: '已选择 1 份'}).waitFor();
    await page.locator('#upload-button').click();
    await page.locator('#status').filter({hasText: '资料已建立索引'}).waitFor({timeout: 60000});
    await page.locator('#document-type').selectOption('exam');
    await page.locator('#files').setInputFiles(path.resolve('data/exam-samples/2025期末练习卷.docx'));
    await page.locator('#upload-button').click();
    await page.locator('#status').filter({hasText: '资料已建立索引'}).waitFor({timeout: 60000});
    results.drag_upload = true;
    await page.locator('#question').fill('解释2025期末第12题');
    await page.locator('#question').press('Control+Enter');
    await page.locator('#result').waitFor({timeout: 60000});
    await page.locator('#trace-panel summary').click();
    assert.equal(await page.locator('.tool-step').count(), 3);
    assert.ok(await page.locator('#sources .source').count());
    results.agent_chain = true;
    const navigate = view => page.locator(`.nav-item[data-view="${view}"]`).click();
    await navigate('exams');
    await page.locator('#question-search-form button').click();
    await page.locator('#question-list .question-item').nth(5).waitFor();
    const first = page.locator('#question-list .question-item').first();
    await first.locator('.practice-box summary').click();
    await first.locator('.practice-box textarea').fill('我将 g 和 h 混淆了');
    await first.locator('.practice-box input').fill('混淆实际与估计代价');
    await first.getByRole('button', {name: '需要再练 · 加入错题'}).click();
    await page.locator('#stat-wrong').filter({hasText: '1'}).waitFor({state: 'attached'});
    await navigate('learning');
    await page.locator('#wrongbook .wrong-item').waitFor();
    await page.locator('#accuracy-note').filter({hasText: '正确率 0%'}).waitFor();
    await page.locator('#plan-days').fill('3');
    await page.locator('#plan-minutes').fill('20');
    await page.locator('#plan-button').click();
    await page.locator('#plans .plan-card').waitFor();
    await page.locator('#plans .plan-task input').first().check();
    await page.locator('#plans .count-pill').filter({hasText: '1 / 3'}).waitFor();
    const wrong = page.locator('#wrongbook .wrong-item').first();
    await wrong.locator('.practice-box summary').click();
    await wrong.getByRole('button', {name: '已掌握 · 记录练习'}).click();
    await page.locator('#wrongbook .empty').waitFor();
    await page.locator('#accuracy-note').filter({hasText: '正确率 100%'}).waitFor();
    results.wrongbook_and_self_assessment = true;
    results.plan_checklist = true;
    await page.locator('#include-mastered').check();
    await page.locator('#wrongbook .mastered').waitFor();
    await navigate('generation');
    await page.locator('#generation-kind').selectOption('mock_exam');
    await page.locator('#generation-topics').fill('A* 评价函数');
    await page.locator('#generate-button').click();
    await page.locator('#generation-status').filter({hasText: '已生成并保存'}).waitFor({timeout: 60000});
    assert.equal(await page.locator('#artifact-content .question-item').count(), 3);
    const generated = page.locator('#artifact-content .question-item').first();
    await generated.locator('.practice-box summary').click();
    await generated.getByRole('button', {name: '需要再练 · 加入错题'}).click();
    await page.locator('#toast').filter({hasText: '加入错题本'}).waitFor();
    const downloadEvent = page.waitForEvent('download');
    await page.getByRole('link', {name: '下载题目卷（不附答案）'}).click();
    const text = fs.readFileSync(await (await downloadEvent).path(), 'utf8');
    assert.ok(!text.includes('## 参考答案与解析'));
    results.generated_practice_and_download = true;
    await page.reload();
    await page.locator('#stat-attempts').filter({hasText: '3'}).waitFor();
    assert.equal(await page.locator('#course').inputValue(), course);
    await navigate('learning');
    await page.locator('#plans .count-pill').filter({hasText: '1 / 3'}).waitFor();
    await navigate('history');
    await page.locator('#conversation-history button').first().click();
    await page.locator('#answer').filter({hasText: '未调用 LLM'}).waitFor();
    results.persistence_and_history = true;
    await page.keyboard.press('Control+k');
    await page.locator('#command-search').fill('错题');
    await page.locator('#command-search').press('ArrowDown');
    await page.keyboard.press('Enter');
    await page.locator('#view-learning').waitFor();
    await page.locator('#theme-toggle').click();
    assert.equal(await page.locator('html').getAttribute('data-theme'), 'dark');
    await page.reload();
    assert.equal(await page.locator('html').getAttribute('data-theme'), 'dark');
    results.palette_and_theme = true;
    fs.mkdirSync('data/screenshots', {recursive: true});
    await page.screenshot({path:'data/screenshots/workspace-dark.png',fullPage:true,animations:'disabled'});
    await page.locator('#theme-toggle').click();
    // Verify long-running answers are discarded after switching courses.
    await page.locator('#course-name').fill('课程隔离检查');
    await page.locator('#course-form button').click();
    await page.locator('#status').filter({hasText:'课程已创建'}).waitFor();
    const other = await page.locator('#course').inputValue();
    await page.locator('#course').selectOption(course);
    await page.locator('#stat-attempts').filter({hasText:'3'}).waitFor();
    await page.route('**/api/agent', async route => {
      await new Promise(resolve => setTimeout(resolve, 1200));
      await route.fulfill({json: {answer:'SHOULD_NOT_RENDER',sources:[],questions:[],trace:[],total_ms:1}});
    });
    await page.locator('#question').fill('测试迟到响应');
    await page.locator('#ask-button').click();
    await page.locator('#analysis-progress').waitFor();
    await page.locator('#course').selectOption(other);
    await page.locator('#course').selectOption(course);
    await page.waitForTimeout(1600);
    assert.ok(!(await page.locator('#answer').innerText()).includes('SHOULD_NOT_RENDER'));
    assert.ok(await page.locator('#result').isHidden());
    await page.unroute('**/api/agent');
    results.course_race_guard = true;
    await page.locator('#question').fill('');
    await page.evaluate(() => { document.getElementById('status').textContent = ''; document.getElementById('toast').hidden = true; });
    await page.screenshot({path:'data/screenshots/workspace-desktop.png',fullPage:true,animations:'disabled'});
    await navigate('learning');
    await page.locator('#plans .plan-card').waitFor();
    await page.screenshot({path:'data/screenshots/workspace-learning.png',fullPage:true,animations:'disabled'});
    for (const width of [320,390,768,1024,1440]) {
      await page.setViewportSize({width, height:844});
      await page.waitForTimeout(300);
      assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth > innerWidth),false,`overflow at ${width}`);
    }
    await page.setViewportSize({width:390,height:844});
    await page.waitForTimeout(300);
    await page.locator('#sidebar-toggle').click();
    await page.locator('#sidebar-overlay').waitFor();
    await page.locator('.nav-item[data-view="study"]').click();
    assert.ok(await page.locator('#sidebar-overlay').isHidden());
    await page.screenshot({path:'data/screenshots/workspace-mobile.png',fullPage:true,animations:'disabled'});
    await page.emulateMedia({reducedMotion:'reduce'});
    assert.equal(await page.locator('.float-note').first().evaluate(el=>getComputedStyle(el).animationName),'none');
    results.responsive_widths = [320,390,768,1024,1440];
    results.reduced_motion = true;
    assert.deepEqual(errors, []);
    results.javascript_errors = errors.length;
    fs.writeFileSync('data/screenshots/workspace-verification.json', JSON.stringify(results,null,2));
    console.log(JSON.stringify(results));
  } finally { await browser.close(); }
})().catch(e=>{console.error(e);process.exitCode=1;});
